            String message = String.format("The launcher icon (%s) in the %s folder has an incorrect size. It should be %dx%d px.", name, context.getFolderName(), expected, expected);
            context.report(ISSUE, Location.create(file), message);
        }
    }

    @Override
    public void checkResourceFolder(@NonNull ResourceContext context, @NonNull File folder) { ... }
}
