package com.android.tools.lint.checks;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.ide.common.resources.configuration.DensityQualifier;
import com.android.ide.common.resources.configuration.FolderConfiguration;
import com.android.resources.Density;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.ResourceContext;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;

import java.awt.Dimension;
import java.io.File;
import java.io.IOException;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Iterator;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;

public class IconDetector extends Detector implements Detector.BinaryResourceScanner {

    private static final String LAUNCHER_ICON_NAME = "ic_launcher";
    private static final String LAUNCHER_ROUND_ICON_NAME = "ic_launcher_round";

    private static final Map<Density, Integer> EXPECTED_SIZES;
    static {
        Map<Density, Integer> map = new EnumMap<Density, Integer>(Density.class);
        map.put(Density.LOW, 36);
        map.put(Density.MEDIUM, 48);
        map.put(Density.HIGH, 72);
        map.put(Density.XHIGH, 96);
        map.put(Density.XXHIGH, 144);
        map.put(Density.XXXHIGH, 192);
        EXPECTED_SIZES = Collections.unmodifiableMap(map);
    }

    public static final Issue ICON_EXPECTED_SIZE = Issue.create(
            "IconExpectedSize",
            "Icon has incorrect size",
            "There are predefined sizes (for each density) for launcher icons. You should follow these conventions to make sure your icons fit in with the overall look of the platform.",
            Category.ICONS,
            5,
            Severity.WARNING,
            new Implementation(IconDetector.class, Scope.BINARY_RESOURCE_FILE_SCOPE)
    );

    @Override
    public void checkBinaryResource(@NonNull ResourceContext context) {
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType != ResourceFolderType.MIPMAP && folderType != ResourceFolderType.DRAWABLE) {
            return;
        }

        File file = context.file;
        String fileName = file.getName();
        String baseName = getBaseName(fileName);
        if (!LAUNCHER_ICON_NAME.equals(baseName) && !LAUNCHER_ROUND_ICON_NAME.equals(baseName)) {
            return;
        }

        FolderConfiguration config = context.getFolderConfiguration();
        if (config == null) {
            return;
        }

        DensityQualifier densityQualifier = config.getDensityQualifier();
        if (densityQualifier == null) {
            return;
        }

        Density density = densityQualifier.getValue();
        if (density == null) {
            return;
        }

        Integer expectedSize = EXPECTED_SIZES.get(density);
        if (expectedSize == null) {
            return;
        }

        Dimension size = getImageSize(file);
        if (size == null) {
            return;
        }

        if (size.width != expectedSize || size.height != expectedSize) {
            String folderName = file.getParentFile() != null ? file.getParentFile().getName() : "";
            String message = String.format(
                    "The image %1$s in the %2$s folder has size %3$d x %4$d but should be %5$d x %5$d",
                    fileName, folderName, size.width, size.height, expectedSize);
            context.report(ICON_EXPECTED_SIZE, Location.create(file), message);
        }
    }

    @NonNull
    private static String getBaseName(@NonNull String fileName) {
        int dot = fileName.lastIndexOf('.');
        return dot > 0 ? fileName.substring(0, dot) : fileName;
    }

    @Nullable
    private static Dimension getImageSize(@NonNull File file) {
        try (ImageInputStream input = ImageIO.createImageInputStream(file)) {
            if (input == null) {
                return null;
            }
            Iterator<ImageReader> readers = ImageIO.getImageReaders(input);
            while (readers.hasNext()) {
                ImageReader reader = readers.next();
                reader.setInput(input, true, true);
                try {
                    return new Dimension(reader.getWidth(0), reader.getHeight(0));
                } finally {
                    reader.dispose();
                }
            }
        } catch (IOException e) {
            // Ignore files we cannot read.
        }
        return null;
    }
}
